INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7024629, 1065812, 108069, '<td valign="top">Killer contrast. Great lines in the road and the rays. Very nicely processed. Should do very well.</td>', 'Killer contrast. Great lines in the road and the rays. Very nicely processed. Should do very well.', '2013-04-22 01:37:53.000000', NULL, 1),
(7024630, 1066124, 54446, '<td valign="top">Very competent seascape.  7</td>', 'Very competent seascape.  7', '2013-04-22 01:40:46.000000', NULL, 1),
(7024631, 1066035, 54446, '<td valign="top">I like the scene, but am at a total loss as to why you added SO MUCH frame.  The frame adds nothing to the great scene.  The upper right is cluttered with branches, which seem to obscure valuable parts of the source of the water flow.</td>', 'I like the scene, but am at a total loss as to why you added SO MUCH frame.  The frame adds nothing to the great scene.  The upper right is cluttered with branches, which seem to obscure valuable parts of the source of the water flow.', '2013-04-22 01:42:23.000000', NULL, 1),
(7024636, 1066051, 108069, '<td valign="top">Stunning use of contrast in a minimalistic approach. Killer photo. So very clean. Front page.</td>', 'Stunning use of contrast in a minimalistic approach. Killer photo. So very clean. Front page.', '2013-04-22 01:47:22.000000', NULL, 1),
(7024638, 1065974, 108069, '<td valign="top">Beautiful photo. Nice lines throughout. Well done.</td>', 'Beautiful photo. Nice lines throughout. Well done.', '2013-04-22 01:51:35.000000', NULL, 1),
(7024640, 1066091, 54446, '<td valign="top">I love the treatment.  The foreground rocks, the reflections on the lake, the distant city lights and the snow-capped mountains combine to create a 3 dimensional effect.  This should be a ribbon contender.  10</td>', 'I love the treatment.  The foreground rocks, the reflections on the lake, the distant city lights and the snow-capped mountains combine to create a 3 dimensional effect.  This should be a ribbon contender.  10', '2013-04-22 01:52:24.000000', NULL, 1),
(7024642, 1066072, 54446, '<td valign="top">Love this!  Great texture and flow  It''s unique and special.  Superb leading lines.  This is a work of art.  10</td>', 'Love this!  Great texture and flow  It''s unique and special.  Superb leading lines.  This is a work of art.  10', '2013-04-22 01:52:33.000000', NULL, 1),
(7024644, 1065143, 54446, '<td valign="top">Great, great, great sky.  Good leading lines road.  Should be a top 10.  9</td>', 'Great, great, great sky.  Good leading lines road.  Should be a top 10.  9', '2013-04-22 01:53:24.000000', NULL, 1),
(7024645, 1065973, 108069, '<td valign="top">Awesome photo. Excellent exposure to get detail in the shore. Front pager.</td>', 'Awesome photo. Excellent exposure to get detail in the shore. Front pager.', '2013-04-22 01:53:31.000000', NULL, 1),
(7024646, 1065868, 54446, '<td valign="top">This is very good.  It needs an additional element of interest.  The sky is clear and would have been more interesting with some clouds.   I do like the look down into the lake bottom in the foreground.   8</td>', 'This is very good.  It needs an additional element of interest.  The sky is clear and would have been more interesting with some clouds.   I do like the look down into the lake bottom in the foreground.   8', '2013-04-22 01:55:26.000000', NULL, 1),
(7024648, 1065807, 54446, '<td valign="top">Very nice.  It''s really magical.  I think you need some broader tonal range, especially in the midtone sky.  8</td>', 'Very nice.  It''s really magical.  I think you need some broader tonal range, especially in the midtone sky.  8', '2013-04-22 01:57:31.000000', NULL, 1),
(7024649, 1066077, 108069, '<td valign="top">Very nice. I really like this composition. Falls look excellent. Great stuff.</td>', 'Very nice. I really like this composition. Falls look excellent. Great stuff.', '2013-04-22 01:59:11.000000', NULL, 1),
(7024651, 1066107, 54446, '<td valign="top">That storm was on my head.  I like the stormy sky and the snow falling over the front range.  <br/>good detail in the foreground creating three dimensional effect.  9</td>', 'That storm was on my head.  I like the stormy sky and the snow falling over the front range.  good detail in the foreground creating three dimensional effect.  9', '2013-04-22 02:01:25.000000', NULL, 1),
(7024656, 1065411, 54446, '<td valign="top">The rounded corner vignette is a big distraction from the otherwise very pleasant rural scene.  The sky is featureless and should have been minimized.  The horizon is middle vertical, which creates a dilemma for the viewer.  The foreground shadow area is a distraction.</td>', 'The rounded corner vignette is a big distraction from the otherwise very pleasant rural scene.  The sky is featureless and should have been minimized.  The horizon is middle vertical, which creates a dilemma for the viewer.  The foreground shadow area is a distraction.', '2013-04-22 02:07:40.000000', NULL, 1),
(7024658, 1066024, 54446, '<td valign="top">Not a bad urban scene, but are you not seeing the numerous dust bunnies?  I don''t want to offend you, but please clean your sensor.</td>', 'Not a bad urban scene, but are you not seeing the numerous dust bunnies?  I don''t want to offend you, but please clean your sensor.', '2013-04-22 02:13:57.000000', NULL, 1),
(7024659, 1065724, 54446, '<td valign="top">Overprocessed.  Too surreal.  Horizon is vertical middle.  Needs an additional foreground element of interest.</td>', 'Overprocessed.  Too surreal.  Horizon is vertical middle.  Needs an additional foreground element of interest.', '2013-04-22 02:18:33.000000', NULL, 1),
(7024660, 1065802, 54446, '<td valign="top">Big frame/border  = big distraction.</td>', 'Big frame/border  = big distraction.', '2013-04-22 02:19:51.000000', NULL, 1),
(7024663, 1065743, 54446, '<td valign="top">The people are a big distraction.  Takes away from awesome detail and light in the main part of the image.  The lens flare is a distraciton.  This could have been terrific.</td>', 'The people are a big distraction.  Takes away from awesome detail and light in the main part of the image.  The lens flare is a distraciton.  This could have been terrific.', '2013-04-22 02:23:24.000000', NULL, 1),
(7024687, 1065735, 15511, '<td valign="top">The lightest shades could be lighter - showing the full range of tones available. Really like the rural positioned with the urban here.</td>', 'The lightest shades could be lighter - showing the full range of tones available. Really like the rural positioned with the urban here.', '2013-04-22 03:02:23.000000', NULL, 1),
(7024702, 1065929, 49109, '<td valign="top">Not the most pleasant view of a beach, but very well shot and excellently converted to bw, looks natural and sunny</td>', 'Not the most pleasant view of a beach, but very well shot and excellently converted to bw, looks natural and sunny', '2013-04-22 03:46:51.000000', NULL, 1),
(7024704, 1065144, 49109, '<td valign="top">beautiful light and structures. crop at top seems to be too close, makes we want to see what''s up there</td>', 'beautiful light and structures. crop at top seems to be too close, makes we want to see what''s up there', '2013-04-22 03:48:30.000000', NULL, 1),
(7024706, 1065748, 49109, '<td valign="top">beautiful sky, the ground looks too greyish</td>', 'beautiful sky, the ground looks too greyish', '2013-04-22 03:50:31.000000', NULL, 1),
(7024707, 1065724, 49109, '<td valign="top">Not! Really! To me it looks rather like an overprocesssed sky that doesn''t match the light on the building</td>', 'Not! Really! To me it looks rather like an overprocesssed sky that doesn''t match the light on the building', '2013-04-22 03:52:11.000000', NULL, 1),
(7024708, 1065933, 49109, '<td valign="top">Exactly. Well converted to bw, though.</td>', 'Exactly. Well converted to bw, though.', '2013-04-22 03:52:51.000000', NULL, 1),
(7024712, 1065146, 49109, '<td valign="top">A bit dark at the lower edge, otherwise gorgeous landscape</td>', 'A bit dark at the lower edge, otherwise gorgeous landscape', '2013-04-22 03:57:20.000000', NULL, 1),
(7024728, 1065752, 97225, '<td valign="top">A very dramatic image which reminds me of an illustration of the Tower of Babel which I once saw in a book of bible stories for children. Something is brewing here for sure. Top pick. 10</td>', 'A very dramatic image which reminds me of an illustration of the Tower of Babel which I once saw in a book of bible stories for children. Something is brewing here for sure. Top pick. 10', '2013-04-22 04:14:22.000000', NULL, 1),
(7024752, 1065366, 92577, '<td valign="top">Simply cropping out the bu!ilding would make this much stronger. Other than that its great</td>', 'Simply cropping out the bu!ilding would make this much stronger. Other than that its great', '2013-04-22 06:57:52.000000', NULL, 1),
(7024799, 1065813, 54446, '<td valign="top">Superb focus and clarity.  Love the detail.  Would benefit from something more than 800 pixels.  I like the tonal range.</td>', 'Superb focus and clarity.  Love the detail.  Would benefit from something more than 800 pixels.  I like the tonal range.', '2013-04-22 09:41:49.000000', NULL, 1),
(7024802, 1065565, 54446, '<td valign="top">Remarkable weather event over the city.  This has amazing tonal range.  Superb conversion.  Fisheye lens, I guess.  Well done!</td>', 'Remarkable weather event over the city.  This has amazing tonal range.  Superb conversion.  Fisheye lens, I guess.  Well done!', '2013-04-22 09:43:26.000000', NULL, 1),
(7024803, 1066013, 54446, '<td valign="top">Long exposure.  Good control of detail in the shadows.  Not sure about the toning...Copper maybe... possible distraction.  Technically superb.  Compositition is top notch.</td>', 'Long exposure.  Good control of detail in the shadows.  Not sure about the toning...Copper maybe... possible distraction.  Technically superb.  Compositition is top notch.', '2013-04-22 09:45:48.000000', NULL, 1),
(7024806, 1065146, 54446, '<td valign="top">Good capture of layered fog.  It''s dream-like.  The lower 1/3 of the image is weaker than the top 2/3.  Overall, a compelling image.</td>', 'Good capture of layered fog.  It''s dream-like.  The lower 1/3 of the image is weaker than the top 2/3.  Overall, a compelling image.', '2013-04-22 09:47:54.000000', NULL, 1),
(7024807, 1066034, 92577, '<td valign="top">a bit too much empty sky here</td>', 'a bit too much empty sky here', '2013-04-22 09:47:54.000000', NULL, 1),
(7024808, 1066124, 92577, '<td valign="top">gorgeous</td>', 'gorgeous', '2013-04-22 09:49:01.000000', NULL, 1),
(7024811, 1065812, 54446, '<td valign="top">Love the sky.  The land portion, while good, does not balance the emotion of the sky.   Your perspective point is too low.  Sometimes, when facing this dilemma, I climb up on top of my vehicle.  Sometimes just an extra 6'' of elevation gain gives the scene a better composition.</td>', 'Love the sky.  The land portion, while good, does not balance the emotion of the sky.   Your perspective point is too low.  Sometimes, when facing this dilemma, I climb up on top of my vehicle.  Sometimes just an extra 6'' of elevation gain gives the scene a better composition.', '2013-04-22 09:50:58.000000', NULL, 1),
(7024813, 1065956, 54446, '<td valign="top">This is well seen and photographed.  Love the wet pavement.  Good capture of light.  Great bridge and river channel.</td>', 'This is well seen and photographed.  Love the wet pavement.  Good capture of light.  Great bridge and river channel.', '2013-04-22 09:52:32.000000', NULL, 1),
