(7025314, 1066027, 136989, '<td valign="top">Wonderful details.  A simple scene yet it speaks volumes.  Love it.</td>', 'Wonderful details.  A simple scene yet it speaks volumes.  Love it.', '2013-04-23 01:22:03.000000', NULL, 1),
(7025316, 1065480, 136989, '<td valign="top">My fav in this challenge. What a wonderful scene.  That tree is full of character and I love how the branch frames the serenity of the fields and rolling hills.</td>', 'My fav in this challenge. What a wonderful scene.  That tree is full of character and I love how the branch frames the serenity of the fields and rolling hills.', '2013-04-23 01:25:57.000000', NULL, 1),
(7025342, 1065480, 86218, '<td valign="top">Love this. Pretty, prettier... prettiest. It''s not just the tree. Youve doen a good job of making the whole scene flow with implied and definate lines.<br/>Great work</td>', 'Love this. Pretty, prettier... prettiest. It''s not just the tree. Youve doen a good job of making the whole scene flow with implied and definate lines.Great work', '2013-04-23 06:52:55.000000', NULL, 1),
(7025343, 1065602, 86218, '<td valign="top">Funny how this very basic scene has so much appeal. Lighting has much to do with this and love the strong backlighting in it and the blacks in those "dead trees" etc with the white clouds contrasted well. The river generates a calm mood here in a seemingly lifeless enviroment. A cyclic story to be told here</td>', 'Funny how this very basic scene has so much appeal. Lighting has much to do with this and love the strong backlighting in it and the blacks in those "dead trees" etc with the white clouds contrasted well. The river generates a calm mood here in a seemingly lifeless enviroment. A cyclic story to be told here', '2013-04-23 07:00:03.000000', NULL, 1),
(7025472, 1066123, 78757, '<td valign="top">UNISA... I do miss those South African skies.</td>', 'UNISA... I do miss those South African skies.', '2013-04-23 10:45:21.000000', NULL, 1),
(7025503, 1066045, 16046, '<td valign="top">Lack of title loses points</td>', 'Lack of title loses points', '2013-04-23 12:32:33.000000', NULL, 1),
