(7025536, 1065752, 30712, '<td valign="top">It''s the impact of this image that makes this the bes//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1065752#t of the bunch.  Stunning!</td>', 'It''s the impact of this image that makes this the bes//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1065752#t of the bunch.  Stunning!', '2013-04-23 13:59:10.000000', NULL, 1),
(7025537, 1065717, 30712, '<td valign="top">This glows with quality.  A lovely combination of shape and form.</td>', 'This glows with quality.  A lovely combination of shape and form.', '2013-04-23 14:00:25.000000', NULL, 1),
(7025539, 1065565, 30712, '<td valign="top">The contrast here is wonderful with good darks and glowing lights.  Tall buildings seem to have even more of an impression of togetherness when curved like this.</td>', 'The contrast here is wonderful with good darks and glowing lights.  Tall buildings seem to have even more of an impression of togetherness when curved like this.', '2013-04-23 14:02:17.000000', NULL, 1),
