(7025541, 1065146, 30712, '<td valign="top">This has a delightful air of mystery and surprise.</td>', 'This has a delightful air of mystery and surprise.', '2013-04-23 14:03:59.000000', NULL, 1),
(7025550, 1065658, 159200, '<td valign="top">I like the way the buildings gradually progress into the distance - clever.</td>', 'I like the way the buildings gradually progress into the distance - clever.', '2013-04-23 14:44:11.000000', NULL, 1),
(7025555, 1065810, 159200, '<td valign="top">The colours seem to overpower the detail in the picture.. Maybe having the colours a little less extreme would help?</td>', 'The colours seem to overpower the detail in the picture.. Maybe having the colours a little less extreme would help?', '2013-04-23 14:47:16.000000', NULL, 1),
