(7025679, 1066107, 114225, '<td valign="top">Flat but interesting.</td>', 'Flat but interesting.', '2013-04-23 19:47:08.000000', NULL, 1),
(7025680, 1065823, 114225, '<td valign="top">I really enjoy the way the road runs through this.</td>', 'I really enjoy the way the road runs through this.', '2013-04-23 19:48:22.000000', NULL, 1),
(7025684, 1066056, 114225, '<td valign="top">I''m liking the middle composition, especially since the edges have mirrored smaller trees.</td>', 'I''m liking the middle composition, especially since the edges have mirrored smaller trees.', '2013-04-23 19:55:51.000000', NULL, 1),
(7025686, 1065977, 114225, '<td valign="top">Nice find. Although I find the image a little disorienting. The weight of the right side of he image is so heavy, and the perspective makes this look tilted.</td>', 'Nice find. Although I find the image a little disorienting. The weight of the right side of he image is so heavy, and the perspective makes this look tilted.', '2013-04-23 19:57:34.000000', NULL, 1),
(7025687, 1065454, 114225, '<td valign="top">I enjoy how this looks like you are emerging from the forest to find the ocean.</td>', 'I enjoy how this looks like you are emerging from the forest to find the ocean.', '2013-04-23 19:58:10.000000', NULL, 1),
(7025688, 1065813, 114225, '<td valign="top">Very nice set of buildings.</td>', 'Very nice set of buildings.', '2013-04-23 19:58:28.000000', NULL, 1),
(7025689, 1065885, 114225, '<td valign="top">I like the minimalistic landscape on display here.</td>', 'I like the minimalistic landscape on display here.', '2013-04-23 19:58:55.000000', NULL, 1),
(7025690, 1065752, 114225, '<td valign="top">A good use for a fisheye lens.<br/> <br/>And that reflection on the tower is perfect.</td>', 'A good use for a fisheye lens. And that reflection on the tower is perfect.', '2013-04-23 19:59:49.000000', NULL, 1),
(7025691, 1066085, 114225, '<td valign="top">I really enjoy the mood that this image portrays.</td>', 'I really enjoy the mood that this image portrays.', '2013-04-23 20:00:05.000000', NULL, 1),
(7025692, 1066077, 114225, '<td valign="top">A very different composition of this popular falls.</td>', 'A very different composition of this popular falls.', '2013-04-23 20:00:39.000000', NULL, 1),
(7025693, 1065731, 114225, '<td valign="top">There is something about the lines caused by the power lines that is eerie.</td>', 'There is something about the lines caused by the power lines that is eerie.', '2013-04-23 20:01:06.000000', NULL, 1),
(7025694, 1065807, 114225, '<td valign="top">Nice. I really like this view.</td>', 'Nice. I really like this view.', '2013-04-23 20:01:16.000000', NULL, 1),
(7025695, 1065922, 114225, '<td valign="top">I really really enjoy how the flowers make little pops of white on the ground.</td>', 'I really really enjoy how the flowers make little pops of white on the ground.', '2013-04-23 20:02:01.000000', NULL, 1),
(7025697, 1065248, 114225, '<td valign="top">Excellent mixture of texture in this image.</td>', 'Excellent mixture of texture in this image.', '2013-04-23 20:02:13.000000', NULL, 1),
(7025698, 1065894, 114225, '<td valign="top">A beautiful image.</td>', 'A beautiful image.', '2013-04-23 20:02:22.000000', NULL, 1),
(7025699, 1065733, 114225, '<td valign="top">The lines are so cool, and the offset of the trees works wonders.</td>', 'The lines are so cool, and the offset of the trees works wonders.', '2013-04-23 20:02:37.000000', NULL, 1),
(7025700, 1066024, 114225, '<td valign="top">Watch out for that sensor dust!</td>', 'Watch out for that sensor dust!', '2013-04-23 20:03:09.000000', NULL, 1),
(7025701, 1065669, 114225, '<td valign="top">This perspective gives a feeling of the building sinking into the ground over time. Nicely done.</td>', 'This perspective gives a feeling of the building sinking into the ground over time. Nicely done.', '2013-04-23 20:03:33.000000', NULL, 1),
(7025702, 1065818, 114225, '<td valign="top">This image is really wanting some perspective correction so the buildings aren''t falling over.</td>', 'This image is really wanting some perspective correction so the buildings aren''t falling over.', '2013-04-23 20:04:14.000000', NULL, 1),
(7025703, 1065743, 114225, '<td valign="top">The way the filtered light highlights the children is magical.</td>', 'The way the filtered light highlights the children is magical.', '2013-04-23 20:04:27.000000', NULL, 1),
(7025704, 1065956, 114225, '<td valign="top">I really like the way you exposed this image.</td>', 'I really like the way you exposed this image.', '2013-04-23 20:05:05.000000', NULL, 1),
(7025705, 1066072, 114225, '<td valign="top">What a wonderful find!</td>', 'What a wonderful find!', '2013-04-23 20:05:22.000000', NULL, 1),
(7025706, 1065973, 114225, '<td valign="top">A beautiful use of a long exposure.</td>', 'A beautiful use of a long exposure.', '2013-04-23 20:05:32.000000', NULL, 1),
(7025707, 1065959, 114225, '<td valign="top">Wonderful place to grab this shot from.</td>', 'Wonderful place to grab this shot from.', '2013-04-23 20:05:42.000000', NULL, 1),
(7025708, 1065480, 114225, '<td valign="top">Lovely scene that shows the beauty of spring.</td>', 'Lovely scene that shows the beauty of spring.', '2013-04-23 20:06:01.000000', NULL, 1),
(7025709, 1065144, 114225, '<td valign="top">Wonderful filtered light!</td>', 'Wonderful filtered light!', '2013-04-23 20:07:05.000000', NULL, 1),
