(7025711, 1065481, 114225, '<td valign="top">Very nicely done. The exposure time is perfect for creating that chaos effect.</td>', 'Very nicely done. The exposure time is perfect for creating that chaos effect.', '2013-04-23 20:07:50.000000', NULL, 1),
(7025714, 1065931, 114225, '<td valign="top">What a wonderful scene to display.</td>', 'What a wonderful scene to display.', '2013-04-23 20:08:19.000000', NULL, 1),
(7025716, 1065868, 114225, '<td valign="top">I really enjoy when you can see into the water light this, and then it merges into a reflection.</td>', 'I really enjoy when you can see into the water light this, and then it merges into a reflection.', '2013-04-23 20:09:08.000000', NULL, 1),
(7025717, 1066087, 114225, '<td valign="top">A classic shot with perfect contrast.</td>', 'A classic shot with perfect contrast.', '2013-04-23 20:09:21.000000', NULL, 1),
(7025718, 1065972, 114225, '<td valign="top">Looks so little from this perspective. Nicely done.</td>', 'Looks so little from this perspective. Nicely done.', '2013-04-23 20:09:44.000000', NULL, 1),
(7025719, 1065146, 114225, '<td valign="top">The revelation of a morning fog. Excellent.</td>', 'The revelation of a morning fog. Excellent.', '2013-04-23 20:10:06.000000', NULL, 1),
(7025728, 1065834, 10785, '<td valign="top">Good tones and textures throughout but the angle leaves us with little to look at.</td>', 'Good tones and textures throughout but the angle leaves us with little to look at.', '2013-04-23 20:28:54.000000', NULL, 1),
(7025730, 1065981, 10785, '<td valign="top">This is coming off as very crunchy. I think the sharpness is kicked up a little too high.</td>', 'This is coming off as very crunchy. I think the sharpness is kicked up a little too high.', '2013-04-23 20:30:47.000000', NULL, 1),
(7025731, 1065886, 10785, '<td valign="top">Looks like the rail yard right down in Philladelphia.</td>', 'Looks like the rail yard right down in Philladelphia.', '2013-04-23 20:31:41.000000', NULL, 1),
(7025733, 1065570, 10785, '<td valign="top">Looking at this the first thing I can see is all the highlights are blown in the sky and the shadows are barely existent. I can imagine this histogram peaks to the right. The midtones look ok, but there is a lack of contrast throughout.</td>', 'Looking at this the first thing I can see is all the highlights are blown in the sky and the shadows are barely existent. I can imagine this histogram peaks to the right. The midtones look ok, but there is a lack of contrast throughout.', '2013-04-23 20:34:24.000000', NULL, 1),
(7025734, 1065480, 10785, '<td valign="top">Pastoral!</td>', 'Pastoral!', '2013-04-23 20:34:43.000000', NULL, 1),
(7025735, 1065731, 10785, '<td valign="top">It is very evident you used some exposure adjustment brush on the sky as it is much darker than the lit area on the truck. The line of the halo along the horizon makes it obvious that the blending was not done with much detail.</td>', 'It is very evident you used some exposure adjustment brush on the sky as it is much darker than the lit area on the truck. The line of the halo along the horizon makes it obvious that the blending was not done with much detail.', '2013-04-23 20:36:35.000000', NULL, 1),
(7025736, 1065146, 10785, '<td valign="top">An alternate title could be "Luminous Layers" Because this shot has multiple layers of soft luminosity thrpughout the foreground, midground and background! Lovely shot that I hope wins a ribbon!</td>', 'An alternate title could be "Luminous Layers" Because this shot has multiple layers of soft luminosity thrpughout the foreground, midground and background! Lovely shot that I hope wins a ribbon!', '2013-04-23 20:38:38.000000', NULL, 1),
(7025737, 1065992, 10785, '<td valign="top">I think this could be a case where getting a little closer to the trees could have helped to isolate them from the background and help create a bigger foreground element. But I love the tones of the shot to create the mood.</td>', 'I think this could be a case where getting a little closer to the trees could have helped to isolate them from the background and help create a bigger foreground element. But I love the tones of the shot to create the mood.', '2013-04-23 20:40:32.000000', NULL, 1),
(7025875, 1065812, 112828, '<td valign="top">Big dramatic skies!  Good leading lines too.</td>', 'Big dramatic skies!  Good leading lines too.', '2013-04-23 22:17:38.000000', NULL, 1),
(7025886, 1066071, 46918, '<td valign="top">Way too overexposed for me</td>', 'Way too overexposed for me', '2013-04-23 23:04:44.000000', NULL, 1),
