(7026551, 1066004, 58610, '<td valign="top">Very dramatic. I''d like it with a bit less contrast, though.</td>', 'Very dramatic. I''d like it with a bit less contrast, though.', '2013-04-24 18:18:35.000000', NULL, 1),
(7026554, 1065570, 58610, '<td valign="top">Good lines and nice use of rule of thirds. The overexposed sky takes away from the overall composition.</td>', 'Good lines and nice use of rule of thirds. The overexposed sky takes away from the overall composition.', '2013-04-24 18:21:49.000000', NULL, 1),
(7026557, 1065743, 58610, '<td valign="top">Nice capture. Nearly falls into the category of environmental portrait. Very well done.</td>', 'Nice capture. Nearly falls into the category of environmental portrait. Very well done.', '2013-04-24 18:25:08.000000', NULL, 1),
(7026560, 1065835, 58610, '<td valign="top">To me, using a portrait orientation truncates the landscape and makes me want more of this otherwise beautiful photo.</td>', 'To me, using a portrait orientation truncates the landscape and makes me want more of this otherwise beautiful photo.', '2013-04-24 18:27:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7026562, 1065982, 58610, '<td valign="top">Yes. Why not. From black to white and everything in between. Plus a pleasing composition with lots of interest and detail. Nice.</td>', 'Yes. Why not. From black to white and everything in between. Plus a pleasing composition with lots of interest and detail. Nice.', '2013-04-24 18:31:27.000000', NULL, 1),
(7026567, 1065622, 58610, '<td valign="top">I love the southwest, but i''ve never been here. Definitely going on my "to do" list. Great sky, good comp.</td>', 'I love the southwest, but i''ve never been here. Definitely going on my "to do" list. Great sky, good comp.', '2013-04-24 18:39:04.000000', NULL, 1),
(7026568, 1065890, 58610, '<td valign="top">Very powerful composition and leading lines. I wish the sky wasn''t blown out, and that there was a pedestrian in the shot somewhere.</td>', 'Very powerful composition and leading lines. I wish the sky wasn''t blown out, and that there was a pedestrian in the shot somewhere.', '2013-04-24 18:41:21.000000', NULL, 1),
(7026569, 1065858, 58610, '<td valign="top">What an incredible scene, though the sky is almost overpowering. Good composition with smooth gradation from blacks to whites.</td>', 'What an incredible scene, though the sky is almost overpowering. Good composition with smooth gradation from blacks to whites.', '2013-04-24 18:44:06.000000', NULL, 1),
(7026570, 1065735, 58610, '<td valign="top">Overall just a bit too dark, and too bad the dog wasn''t on the other side. Interesting scene.</td>', 'Overall just a bit too dark, and too bad the dog wasn''t on the other side. Interesting scene.', '2013-04-24 18:45:27.000000', NULL, 1),
(7026571, 1065733, 113411, '<td valign="top">Great shot! Is this Zion?</td>', 'Great shot! Is this Zion?', '2013-04-24 18:53:09.000000', NULL, 1),
(7026695, 1065894, 86218, '<td valign="top">Lovely shot and fitting title. Might get hammered as not entirely in the landscape frame of what everybody is shooting and posting.</td>', 'Lovely shot and fitting title. Might get hammered as not entirely in the landscape frame of what everybody is shooting and posting.', '2013-04-25 07:36:31.000000', NULL, 1),
(7026768, 1065947, 30669, '<td valign="top">A very interesting looking place.</td>', 'A very interesting looking place.', '2013-04-25 12:06:16.000000', NULL, 1),
(7026797, 1065730, 52267, '<td valign="top">My favorite of the challenge. Nice processing.</td>', 'My favorite of the challenge. Nice processing.', '2013-04-25 13:02:56.000000', NULL, 1),
(7026966, 1066091, 148750, '<td valign="top">Neat photo.  It looks like the shoreline is on fire.</td>', 'Neat photo.  It looks like the shoreline is on fire.', '2013-04-25 19:03:30.000000', NULL, 1),
