(7028395, 1065248, 124815, '<td valign="top">slick; perhaps too slick</td>', 'slick; perhaps too slick', '2013-04-28 20:55:08.000000', NULL, 1),
(7028396, 1065752, 112739, '<td valign="top">I love how you used the wide lens to capture the building, but at a cost of distortion on the sides. I wonder how a tilt /shift lens would handle this incredibly tall building.</td>', 'I love how you used the wide lens to capture the building, but at a cost of distortion on the sides. I wonder how a tilt /shift lens would handle this incredibly tall building.', '2013-04-28 20:56:48.000000', NULL, 1),
